public class Probe { public static String rows() throws Exception { String j="{\"schemaVersion\":1,\"id\":\"demo\",\"version\":\"1.0.0\",\"custom\":{\"demo:cfg\":{\"zeta\":1,\"alpha\":\"a\",\"nested\":{\"y\":true,\"x\":null},\"list\":[1,\"two\",false],\"alpha\":\"again\",\"num\":2.5}}}"; Method m=Class.forName("net.fabricmc.loader.impl.metadata.ModMetadataParser").getDeclaredMethod("readModMetadata",InputStream.class,boolean.class); m.setAccessible(true); Object md=m.invoke(null,new ByteArrayInputStream(j.getBytes()),false); CustomValue.CvObject o=((net.fabricmc.loader.impl.metadata.LoaderModMetadata)md).getCustomValue("demo:cfg").getAsObject(); StringBuilder b=new StringBuilder(); var it=o.iterator(); while(it.hasNext()){var e=it.next(); b.append(e.getKey()).append('=').append(e.getValue().getType()).append(':').append(e.getValue()).append('|');} try{it.remove();}catch(Exception e){b.append("remove=").append(e.getClass().getName()).append('|');} b.append("size=").append(o.size()); return b.toString(); } public static void main(String[] a)throws Exception{System.out.print(rows());}}
